<?php if ($result): ?><section class="result"><small>YOUR PLAN</small><h2><?= $h($values['origin']) ?> → <?= $h($values['destination']) ?></h2><p><?= $h($values['departure_date']) ?><?= $values['return_date']?' 〜 '.$h($values['return_date']):'' ?>・<?= $values['return_date']!==''?'往復':'片道' ?>・<?= $h($values['travelers']) ?>名</p>
<?php if ($flightOffers): ?><div class="flight-offers" aria-label="参考フライト"><?php foreach($flightOffers as $offerIndex=>$offer): ?><article class="flight-offer"<?= $offerIndex>=6?' hidden data-extra-offer':'' ?>><div class="flight-carrier"><?php if($offer['airline_logo']!==''): ?><img src="<?= $h($offer['airline_logo']) ?>" alt="" width="70" height="70" loading="lazy"><?php elseif($offer['carrier_code']!==''): ?><span class="carrier-code"><?= $h($offer['carrier_code']) ?></span><?php endif ?><b><?= $h($offer['carrier_name']) ?></b><span class="flight-stops"><?= $offer['stops']===0?'直行便':$h($offer['stops']).'回乗継' ?></span></div><div class="flight-price"><small>参考価格</small><strong><?= $offer['currency']==='JPY'?'¥':$h($offer['currency']).' ' ?><?= $h($offer['price']) ?></strong></div></article><?php endforeach ?></div><?php if(count($flightOffers)>6): ?><button type="button" class="flight-offers-toggle" aria-expanded="false">もっと見る</button><?php endif ?><p class="price-note">表示価格はGoogle Flightsの検索結果です。最新の価格・空席は各予約サイトでご確認ください。</p>
<?php elseif($flightOffersMessage !== ''): ?><div class="flight-offers-message"><?= $h($flightOffersMessage) ?></div><?php endif ?>
<section class="booking-sites"><h3>予約サイト</h3><p>同じ条件を各予約サイトで確認できます。</p><div class="booking-site-links"><a href="<?= $h($result['flight']) ?>" target="_blank" rel="sponsored noopener">Trip.com</a><a href="<?= $h($result['bookingcom']) ?>" target="_blank" rel="sponsored noopener">Booking.com</a><a href="<?= $h($result['expedia']) ?>" target="_blank" rel="noopener">Expedia</a><a href="<?= $h($result['agoda']) ?>" target="_blank" rel="noopener">Agoda</a><a href="<?= $h($result['ena']) ?>" target="_blank" rel="noopener">ena</a><?php if($isDomesticFlight&&isset($result['sakura'])): ?><a href="<?= $h($result['sakura']) ?>" target="_blank" rel="noopener">さくらトラベル</a><a href="<?= $h($result['airtrip']) ?>" target="_blank" rel="noopener">エアトリ</a><?php endif ?></div></section><div class="actions"><a href="<?= $h($result['maps']) ?>" target="_blank" rel="noopener">Google Maps</a></div><em>予約・決済は各提携先サイトで行われます。</em></section><?php endif ?>
